\frac{58}{13} \begin{pmatrix} 2 \\ 3 \end{pmatrix} & = \frac{2x + 3y}{13} \begin{pmatrix} 2 \\ 3 \end{pmatrix} \\
\frac{116}{13} + \frac{174}{13} & = 2x + 3y \\
\frac{290}{13} & = 2x + 3y
